const { PDFDocument } = require('pdf-lib');
const fontkit = require('@pdf-lib/fontkit');
const fs = require('fs');

(async () => {
  const doc = await PDFDocument.create();
  doc.registerFontkit(fontkit);
  const fontBytes = fs.readFileSync('/usr/share/fonts/workspacex/NotoSansSC-Common.otf');
  const font = await doc.embedFont(fontBytes);

  const pages = [
    { label: 'ALPHA', cjk: '中文甲' },
    { label: 'BETA', cjk: '中文乙' },
    { label: 'GAMMA', cjk: '中文丙' },
  ];

  for (const p of pages) {
    const page = doc.addPage([595, 842]);
    page.drawText(p.label, { x: 50, y: 750, size: 36, font });
    page.drawText(p.cjk, { x: 50, y: 700, size: 28, font });
  }

  fs.writeFileSync('/workspace/source.pdf', await doc.save());
  console.log('source.pdf created');
})().catch(e => { console.error(e.stack); process.exit(1); });

